    {
      "card_ids": ["C60"],
      "claim": "Fluvastatin, an indole with an acidic heptenoic acid side chain, has an absolute oral bioavailability of 24-30%, directly supporting F>=20% for the query's indole-hydroxamate scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Tadalafil, an indole-containing drug, has an oral bioavailability of at least 36%, showing that indole-based molecules can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Ketanserin, a basic amine with polar aromatic groups, has an absolute oral bioavailability of 55.5%, demonstrating that basic/polar drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Propafenone, a secondary amine with extensive first-pass metabolism, has an absolute oral bioavailability of 15%, which would argue for low F; however, its low F is largely due to CYP2D6 metabolism not shared by the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "DMT, an indoleethylamine, has ~10-15% oral bioavailability, but this is driven by rapid MAO first-pass metabolism, a mechanism not applicable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C36"],
      "claim": "Sumatriptan, an indole with a basic amine and polar sulfonamide, has 14% oral bioavailability, but its lower lipophilicity and different polar functionality limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high. The query is an indole-based hydroxamic acid with a basic secondary amine. The most structurally relevant high-F analogues (fluvastatin 24-30%, tadalafil >=36%, ketanserin ~50%) support F>=20%. The low-F analogues either lack the indole-acid motif or owe their low F to specific first-pass/zwitterionic mechanisms not shared by the query. Overall, the evidence supports high with moderate confidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in the provided evidence.",
    "No hydroxamic acid-containing analogue is present; transfer from carboxylic acid (fluvastatin) or other polar groups is indirect.",
    "First-pass metabolism of the query is not directly characterized; some low-F analogues are metabolized by pathways not shared by the query.",
    "Exact human F for the query is not established in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

